#include <bits/stdc++.h>
using namespace std;

// DFS iteracyjny — działa dla ścieżki o milionie wierzchołków bez ryzyka przepełnienia stosu
int main() {
    int n = 1000000;
    vector<vector<int>> adj(n);
    for (int i = 0; i + 1 < n; i++) { adj[i].push_back(i + 1); adj[i + 1].push_back(i); }

    vector<int> rodzic(n, -1), kolejnosc;
    kolejnosc.reserve(n);
    vector<int> st = {0};
    vector<char> odw(n, 0);
    odw[0] = 1;
    while (!st.empty()) {
        int v = st.back();
        st.pop_back();
        kolejnosc.push_back(v);
        for (int u : adj[v])
            if (!odw[u]) { odw[u] = 1; rodzic[u] = v; st.push_back(u); }
    }
    // przetwarzanie „od liści”: odwrotna kolejność odwiedzin (np. rozmiary poddrzew)
    vector<int> rozmiar(n, 1);
    for (int i = n - 1; i > 0; i--) rozmiar[rodzic[kolejnosc[i]]] += rozmiar[kolejnosc[i]];
    cout << rozmiar[0] << ' ' << rozmiar[n - 1] << '\n';   // 1000000 1
}

