    // C++17: structured bindings
    map<string, int> m = {{"ala", 3}, {"ola", 5}};
    for (auto& [imie, wiek] : m) wiek++;
    auto [mn, mx] = minmax({4, 9, 1});

    // C++17: if z inicjalizacją — zmienna widoczna tylko w if/else
    if (auto it = m.find("ola"); it != m.end()) cout << it->second << '\n';   // 6

    // C++20: contains, erase_if, starts_with
    set<int> s = {1, 2, 3, 4};
    cout << s.contains(3) << m.contains("ewa") << '\n';                        // 10
    erase_if(s, [](int x) { return x % 2 == 0; });                              // {1, 3}
    string plik = "zad.cpp";
    cout << plik.ends_with(".cpp") << '\n';                                    // 1

    // C++20: ranges i widoki
    vector<int> v = {5, 2, 8, 1};
    ranges::sort(v);
    for (int i : views::iota(0, 3)) cout << i;                                 // 012
    cout << ' ';
    for (int x : v | views::reverse) cout << x << ' ';                         // 8 5 2 1
    cout << '\n';
    auto parzyste = v | views::filter([](int x) { return x % 2 == 0; });
    for (int x : parzyste) cout << x << ' ';                                   // 2 8
    cout << '\n' << mn << mx << ' ' << ssize(v) - 5 << '\n';                    // 19 -1
