#include <ext/pb_ds/tree_policy.hpp>
using namespace std;
using namespace __gnu_pbds;

template<class T>
using ordered_set = tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;

int main() {
    ordered_set<int> s;
    for (int x : {10, 40, 20, 30}) s.insert(x);       // {10, 20, 30, 40}

    cout << *s.find_by_order(0) << ' ' << *s.find_by_order(2) << '\n';   // 10 30 (k od 0)
    cout << s.order_of_key(25) << ' ' << s.order_of_key(30) << '\n';     // 2 2 (ile < x)
    cout << (s.find_by_order(10) == s.end()) << '\n';                    // 1 — k poza zakresem

    s.erase(20);
    cout << s.order_of_key(40) << ' ' << s.size() << '\n';               // 2 3
}

