using ordered_multiset = tree<pair<int, int>, null_type, less<pair<int, int>>, rb_tree_tag, tree_order_statistics_node_update>;

// liczba inwersji w O(n log n): dla każdego elementu — ile wcześniejszych jest od niego większych
int main() {
    vector<int> a = {3, 1, 2, 3, 1};
    ordered_multiset s;
    long long inw = 0;
    for (int i = 0; i < (int)a.size(); i++) {
        inw += i - (long long)s.order_of_key({a[i], INT_MAX});   // wcześniejsze > a[i] = wszystkie − (≤ a[i])
        s.insert({a[i], i});
    }
    cout << inw << '\n';   // 5
}

