#include <bits/stdc++.h>
using namespace std;

// funkcja przyjmująca dowolną funkcję: szablon (szybko) vs std::function (elastycznie)
template<class F>
long long suma_szablon(int n, F f) { long long s = 0; for (int i = 0; i < n; i++) s += f(i); return s; }
long long suma_function(int n, const function<long long(int)>& f) { long long s = 0; for (int i = 0; i < n; i++) s += f(i); return s; }

int main() {
    auto kw = [](int x) -> long long { return 1LL * x * x; };
    cout << suma_szablon(1000, kw) << ' ' << suma_function(1000, kw) << '\n';   // 332833500 332833500

    vector<function<int(int)>> ops = {
        [](int x) { return x + 1; },
        [](int x) { return x * 2; },
    };
    int v = 5;
    for (auto& op : ops) v = op(v);
    cout << v << '\n';                                                          // 12

    function<int(int)> pusta;
    cout << (pusta ? "ma funkcje" : "pusta") << '\n';                           // pusta
}

