vector<long long> memo(n + 1, -1);
auto fib = [&](auto&& self, int k) -> long long {
    if (k < 2) return k;
    if (memo[k] != -1) return memo[k];
    return memo[k] = self(self, k - 1) + self(self, k - 2);
